(async()=>{
  'use strict';
  if(document.readyState==='loading')await new Promise(r=>document.addEventListener('DOMContentLoaded',r,{once:true}));
  const ui=parent.pilotUI,state=parent.reflowState,api='/api/p/'+encodeURIComponent(state.id),json=async path=>{const r=await fetch(api+'/reflow/'+path);if(!r.ok)throw new Error('缓存读取失败 '+r.status);return r.json();};
  const [map,css,inlineEvidence]=await Promise.all([json('mapping'),fetch(new URL('katex-inline.css',location.href)).then(r=>r.text()),json('math')]);
  window.pdfWebArticleCSS=(await Promise.all(['/web/css/arxiv-article.css','/web/css/reader-theme.css'].map(p=>fetch(p).then(r=>r.text())))).join('\n');
  for(const rec of map.records){const key=['para','heading'].includes(rec.legacy_type)?rec.anchor:rec.anchor+'.caption';const edit=state.reader.edits?.[key];if(!edit?.reverted&&typeof edit?.zh==='string')rec.source_chinese=edit.zh;}
  for(const name of ['pdf-selection','full-adapter','english-math','visuals','source-display']){const s=document.createElement('script');s.src='/web/js/reflow/'+name+'.js';await new Promise((resolve,reject)=>{s.onload=resolve;s.onerror=reject;document.head.append(s);});}
  const [bytes,pack]=await Promise.all([fetch('/p/'+encodeURIComponent(state.id)+'/source.pdf').then(r=>r.arrayBuffer()),fetch(api+'/reflow/pack').then(r=>r.arrayBuffer())]);
  const noop=()=>{},manifest=state.manifest,options={type:'pdf',data:{buf:new Uint8Array(bytes)},annotations:[],readOnly:true,title:state.paper.meta.title_en,authorName:'EasyRead',loggedIn:true,sidebarOpen:false,sidebarWidth:230,sidebarView:'outline',showAnnotations:true,primaryViewState:{pageIndex:0,scale:'page-width'},getSDTPack:async()=>({ok:true,bytes:pack,packVersion:manifest.metadata.SDT_PACK_VERSION,schemaMajorVersion:Number(manifest.metadata.SDT_SCHEMA_VERSION.split('.')[0])}),onSaveAnnotations:noop,onDeleteAnnotations:noop,onConfirm:()=>false,onOpenLink:url=>window.open(url,'_blank','noopener'),onSetDataTransferAnnotations:(transfer,values)=>transfer.setData('text/plain',values.map(v=>v.text).join('\n'))};
  for(const key of ['onOpenTagsPopup','onAddToNote','onToggleSidebar','onChangeSidebarWidth','onChangeSidebarView','onChangeViewState','onChangeActiveView','onCopyImage','onSaveImageAs','onRotatePages','onDeletePages','onToggleContextPane','onToolbarShiftTab','onIframeTab','onBringReaderToFront','onTextSelectionAnnotationModeChange','onSaveCustomThemes','onSetZoom','onSetReadAloudVoice','onSetReadAloudStatus','onPurchaseReadAloudCredits','onLogIn','onOpenReadAloudFirstRunPopup'])options[key]=noop;
  options.onChangeViewState=(view,primary)=>{if(primary!==false&&window.pilot&&!window.pilot.reading&&Number.isInteger(view?.pageIndex))ui.progress?.(window.pilot.progress(view.pageIndex));};
  const shell=document.createElement('style');shell.textContent='.toolbar,#toolbar{display:none!important}#split-view{top:0!important}.primary-view,.secondary-view{top:0!important}';document.head.append(shell);
  const reader=window.createReader(options);await reader._primaryView.initializedPromise;const data=await reader._sdtDocumentSession.getDocument();if(!data)throw new Error('缓存不可用');
  reader._primaryView._pdfRenderer.renderRegionCrops=(pageIndex,rects)=>window.renderReflowRegions(reader,pageIndex,rects);
  window.pilot=await window.makeFullPilot({reader,paper:state.paper,manifest,state:{},map,css,ui,save:ui.save,inlineEvidence,structure:data.structure});await ui.ready(window.pilot);
})().catch(e=>{console.error(e);window.pilotError=String(e.stack||e);parent.pilotUI?.status('阅读器未就绪：'+e.message);});
